  });

  it('renders each page with the template named in its frontmatter', () => {
    withTemp((root) => {
      const contentDir = path.join(root, 'content');
      const outputDir = path.join(root, 'dist');
      fs.mkdirSync(contentDir);
      fs.writeFileSync(
